#include <iostream>
#include <array>

int main() {
    // 1. Summing array elements
    constexpr std::size_t gradesCount = 5;
    std::array<int, gradesCount> grades = {85, 92, 78, 90, 88};
    int total = 0;
    for (std::size_t i = 0; i < grades.size(); ++i) {
        total += grades[i];
    }
    std::cout << "Total score: " << total << "\n";

    // 2. Bar chart distribution for categories (0-9, ..., 90-99, 100)
    constexpr std::size_t distSize = 11;
    std::array<unsigned int, distSize> distribution = {
        0, 0, 0, 0, 0, 0, 0, 1, 2, 2, 0
    };

    std::cout << "Grade distribution:\n";
    for (std::size_t i = 0; i < distribution.size(); ++i) {
        if (i == 0) {
            std::cout << "  0-9: ";
        } else if (i == 10) {
            std::cout << "  100: ";
        } else {
            std::cout << i * 10 << "-" << (i * 10 + 9) << ": ";
        }

        for (unsigned int stars = 0; stars < distribution[i]; ++stars) {
            std::cout << '*';
        }
        std::cout << '\n';
    }

    return 0;
}

#include <iostream>
#include <iomanip>
#include <array>

int main() {
    // Survey ratings from 20 participants, scale 1-5
    constexpr std::size_t responseSize = 20;
    constexpr std::size_t frequencySize = 6; // Indices 0 to 5; ignore index 0

    const std::array<unsigned int, responseSize> responses = {
        1, 2, 5, 4, 3, 5, 2, 1, 3, 1,
        4, 3, 3, 3, 2, 3, 3, 2, 2, 5
    };

    // Zero-initialize frequency counters
    std::array<unsigned int, frequencySize> frequency = {};

    // Tally responses using response value directly as subscript
    for (std::size_t answer = 0; answer < responses.size(); ++answer) {
        ++frequency[responses[answer]];
    }

    std::cout << "Rating" << std::setw(17) << "Frequency" << '\n';
    // Print results for ratings 1 through 5
    for (std::size_t rating = 1; rating < frequency.size(); ++rating) {
        std::cout << std::setw(6) << rating 
                  << std::setw(17) << frequency[rating] << '\n';
    }

    return 0;
}
